package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"sort"
)

type FenwickTree struct {
	val []int64
}

func NewFenwickTree(n int) *FenwickTree {
	return &FenwickTree{
		val: make([]int64, n+1),
	}
}

func (f *FenwickTree) Add(x int, v int64) {
	for x < len(f.val) {
		f.val[x] += v
		x += x & -x
	}
}

func (f *FenwickTree) Sum(x int) int64 {
	if x >= len(f.val) {
		panic("index out of range in FenwickTree.Sum")
	}
	ans := int64(0)
	for x > 0 {
		ans += f.val[x]
		x -= x & -x
	}
	return ans
}

func sieve(n int) []int64 {
	isPrime := make([]bool, n+1)
	for i := range isPrime {
		isPrime[i] = true
	}
	for i := 2; i*i <= n; i++ {
		if isPrime[i] {
			for j := i * i; j <= n; j += i {
				isPrime[j] = false
			}
		}
	}
	lenP := 0
	for i := 2; i <= n; i++ {
		if isPrime[i] {
			lenP++
		}
	}
	prime := make([]int64, 0, lenP)
	for i := 2; i <= n; i++ {
		if isPrime[i] {
			prime = append(prime, int64(i))
		}
	}
	return prime
}

type PrimeCountSolver struct {
	query []int64
	memo  []int64
}

func NewPrimeCountSolver() *PrimeCountSolver {
	return &PrimeCountSolver{
		query: []int64{},
		memo:  []int64{},
	}
}

func (s *PrimeCountSolver) Add(n int64) {
	s.query = append(s.query, n)
}

func (s *PrimeCountSolver) Build() {
	sort.Slice(s.query, func(i, j int) bool { return s.query[i] < s.query[j] })
	s.query = uniqueInt64Slice(s.query)
	n := int64(1)
	if len(s.query) > 0 {
		n = s.query[len(s.query)-1]
	}
	m := int64(1)
	for (m+1)*(m+1) <= n {
		m++
	}
	p := sieve(int(m))
	bound := int64(math.Pow(float64(n), 1.0/3.0))
	bound = bound * bound
	bound += 2

	type pair struct {
		n int64
		k int
	}
	stack := []pair{}
	for _, v := range s.query {
		k := binarySearchByInt64(p, func(pp int64) int {
			pp2 := pp * pp
			if pp2 < v {
				return -1
			} else if pp2 > v {
				return 1
			}
			return 0
		})
		if k.found {
			k.idx++
		}
		stack = append(stack, pair{v: v, k: k.idx})
	}

	type qpair struct {
		k int
		n int64
	}
	query := []qpair{}
	for len(stack) > 0 {
		last := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		nv := last.n
		k := last.k
		if k == 0 {
			continue
		}
		q := p[k-1]
		if q*q > nv {
			x := binarySearchByInt64(p[:k], func(pp int64) int {
				pp2 := pp * pp
				if pp2 < nv {
					return -1
				} else if pp2 > nv {
					return 1
				}
				return 0
			})
			if x.found {
				x.idx++
			}
			stack = append(stack, pair{n: nv, k: x.idx})
		} else if nv <= bound {
			query = append(query, qpair{k: k, n: nv})
		} else {
			stack = append(stack, pair{n: nv, k: k - 1})
			stack = append(stack, pair{n: nv / q, k: k - 1})
		}
	}

	sort.Slice(query, func(i, j int) bool {
		if query[i].k == query[j].k {
			return query[i].n < query[j].n
		}
		return query[i].k < query[j].k
	})
	query = uniqueQPairSlice(query)

	mInt := int(bound)
	bit := NewFenwickTree(mInt)
	for i := 1; i <= mInt; i++ {
		bit.Add(i, 1)
	}
	isPrime := make([]bool, mInt+1)
	for i := range isPrime {
		isPrime[i] = true
	}
	memo := make([]int64, len(query))
	pos := 0
	for i, pp := range p {
		pv := int(pp)
		for j := pv; j <= mInt; j += pv {
			if isPrime[j] {
				bit.Add(j, -1)
			}
			isPrime[j] = false
		}
		for pos < len(query) {
			if query[pos].k > i+1 {
				break
			}
			memo[pos] = bit.Sum(int(query[pos].n))
			pos++
		}
		if pos >= len(query) {
			break
		}
	}

	s.memo = make([]int64, len(s.query))
	type spair struct {
		n    int64
		k    int
		sign int64
		i    int
	}
	stack2 := []spair{}
	for i, nv := range s.query {
		k := binarySearchByInt64(p, func(pp int64) int {
			pp2 := pp * pp
			if pp2 < nv {
				return -1
			} else if pp2 > nv {
				return 1
			}
			return 0
		})
		if k.found {
			k.idx++
		}
		s.memo[i] += int64(k.idx) - 1
		stack2 = append(stack2, spair{n: nv, k: k.idx, sign: 1, i: i})
	}

	for len(stack2) > 0 {
		last := stack2[len(stack2)-1]
		stack2 = stack2[:len(stack2)-1]
		nv := last.n
		k := last.k
		sign := last.sign
		i := last.i
		if k == 0 {
			s.memo[i] += sign * nv
			continue
		}
		q := p[k-1]
		if q*q > nv {
			x := binarySearchByInt64(p[:k], func(pp int64) int {
				pp2 := pp * pp
				if pp2 < nv {
					return -1
				} else if pp2 > nv {
					return 1
				}
				return 0
			})
			if x.found {
				x.idx++
			}
			s.memo[i] += -sign * int64(k-x.idx)
			stack2 = append(stack2, spair{n: nv, k: x.idx, sign: sign, i: i})
		} else if nv <= bound {
			idx := sort.Search(len(query), func(j int) bool {
				if query[j].k == k {
					return query[j].n >= nv
				}
				return query[j].k >= k
			})
			s.memo[i] += sign * memo[idx]
		} else {
			stack2 = append(stack2, spair{n: nv, k: k - 1, sign: sign, i: i})
			stack2 = append(stack2, spair{n: nv / q, k: k - 1, sign: -sign, i: i})
		}
	}
}

func (s *PrimeCountSolver) Get(n int64) int64 {
	idx := sort.Search(len(s.query), func(i int) bool { return s.query[i] >= n })
	return s.memo[idx]
}

func uniqueInt64Slice(a []int64) []int64 {
	if len(a) == 0 {
		return a
	}
	j := 0
	for i := 1; i < len(a); i++ {
		if a[i] != a[j] {
			j++
			a[j] = a[i]
		}
	}
	return a[:j+1]
}

func uniqueQPairSlice(a []struct {
	k int
	n int64
}) []struct {
	k int
	n int64
} {
	if len(a) == 0 {
		return a
	}
	j := 0
	for i := 1; i < len(a); i++ {
		if a[i].k != a[j].k || a[i].n != a[j].n {
			j++
			a[j] = a[i]
		}
	}
	return a[:j+1]
}

type bsResult struct {
	idx   int
	found bool
}

func binarySearchByInt64(arr []int64, cmp func(int64) int) bsResult {
	lo, hi := 0, len(arr)
	for lo < hi {
		mid := (lo + hi) / 2
		c := cmp(arr[mid])
		if c == 0 {
			return bsResult{idx: mid, found: true}
		} else if c < 0 {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return bsResult{idx: lo, found: false}
}

func run() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)
	p := sieve(int(math.Sqrt(float64(n))) + 2)
	ans := int64(0)
	for _, pp := range p {
		if pp*pp*pp <= n {
			ans++
		} else {
			break
		}
	}
	solver := NewPrimeCountSolver()
	for i, pp := range p {
		if pp*pp <= n {
			ans -= int64(i) + 1
			solver.Add(n / pp)
		}
	}
	solver.Build()
	for _, pp := range p {
		if pp*pp <= n {
			ans += solver.Get(n / pp)
		}
	}
	fmt.Println(ans)
}

func main() {
	run()
}

