	for _, v := range s.query {
		k := binarySearchByInt64(p, func(pp int64) int {
			pp2 := pp * pp
			if pp2 < v {
				return -1
			} else if pp2 > v {
				return 1
			}
			return 0
		})
		if k.found {
			k.idx++
		}
		stack = append(stack, pair{v: v, k: k.idx})
	}

	type qpair struct {
		k int
		n int64
	}
	query := []qpair{}
	for len(stack) > 0 {
		last := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		nv, k := last.n, last.k
		if k == 0 {
