		for j := pv; j <= mInt; j += pv {
			if isPrime[j] {
				bit.Add(j, -1)
			}
			isPrime[j] = false
		}
		for pos < len(query) {
			if query[pos].k > i+1 {
				break
			}
			memo[pos] = bit.Sum(int(query[pos].n))
			pos++
		}
		if pos >= len(query) {
			break
		}
	}

	s.memo = make([]int64, len(s.query))
	type spair struct {
		n    int64
		k    int
		sign int64
		i    int
	}
	stack2 := []spair{}
	for i, nv := range s.query {
		k := binarySearchByInt64(p, func(pp int64) int {
			pp2 := pp * pp
			if pp2 < nv {
