		stack2 = append(stack2, spair{n: nv, k: k.idx, sign: 1, i: i})
	}

	for len(stack2) > 0 {
		last := stack2[len(stack2)-1]
		stack2 = stack2[:len(stack2)-1]
		nv, k, sign, idx := last.n, last.k, last.sign, last.i
		if k == 0 {
			s.memo[idx] += sign * nv
			continue
		}
		q := p[k-1]
		if q*q > nv {
			x := binarySearchByInt64(p[:k], func(pp int64) int {
				pp2 := pp * pp
				if pp2 < nv {
					return -1
				} else if pp2 > nv {
					return 1
				}
				return 0
			})
			if x.found {
				x.idx++
			}
			s.memo[idx] += -sign * int64(k-x.idx)
			stack2 = append(stack2, spair{n: nv, k: x.idx, sign: sign, i: idx})
		} else if nv <= bound {
			pos := sort.Search(len(query), func(i int) bool {
				if query[i].k == k {
					return query[i].n >= nv
				}
				return query[i].k >= k
			})
			s.memo[idx] += sign * memo[pos]
		} else {
			stack2 = append(stack2, spair{n: nv, k: k - 1, sign: sign, i: idx})
			stack2 = append(stack2, spair{n: nv / q, k: k - 1, sign: -sign, i: idx})
		}
	}
}

func (s *PrimeCountSolver) Get(n int64) int64 {
