	return s.memo[pos]
}

type bsResult struct {
	idx   int
	found bool
}

func binarySearchByInt64(a []int64, cmp func(int64) int) bsResult {
	lo, hi := 0, len(a)
	for lo < hi {
		mid := (lo + hi) / 2
		c := cmp(a[mid])
		if c == 0 {
			return bsResult{idx: mid, found: true}
		} else if c < 0 {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return bsResult{idx: lo, found: false}
}

